using Godot;
using System;
using System.Linq;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class TimelinePhysicsOperations
{
    private readonly GrowthPhysicsOperations _growth=new();
    public Vector3 gravity(Settings config)=>config["gravity_direction"].AsVector3().Normalized()*config["gravity"].AsSingle();
    public Vector3 environment_wind(RefCounted owner,Resource? actor,double time){if(actor==null)return Vector3.Zero;var worldPosition=animated_world(owner,actor.Get("id").AsString(),time,true,new Settings()).Origin;foreach(var value in Model(owner)!.Get("actors").AsGodotArray()){var environment=value.As<Resource>();if(environment.Get("type_id").AsString()!="environment_asset")continue;var clip=Model(owner)!.Call("clip_for_actor_id",environment.Get("id")).As<Resource>();if(clip==null||!_clips.contains_time(clip,time))continue;var node=runtime(owner,environment.Get("id").AsString());if(node==null||!node.HasMethod("environment_at"))continue;var values=_animation.sampled_values(environment,local(owner,environment,time));var overrides=new Settings{["climate_time"]=Get(values,"climate_time",-1.0).AsDouble(),["climate_weather"]=Get(values,"climate_weather",0).AsInt32(),["climate_intensity"]=Get(values,"climate_intensity",-1.0).AsDouble(),["climate_clouds"]=Get(values,"climate_clouds",-1.0).AsDouble(),["climate_temperature_offset"]=Get(values,"climate_temperature_offset",0.0).AsDouble(),["climate_wind_add"]=Get(values,"climate_wind_add",Vector3.Zero)};return Get(node.Call("environment_at",worldPosition,time,overrides).AsGodotDictionary(),"wind_velocity",Vector3.Zero).AsVector3();}return Vector3.Zero;}
    public Settings events(Settings config,double time,double h){var impulse=Vector3.Zero;var force=Vector3.Zero;foreach(var value in config["forces"].AsGodotArray()){var item=value.AsGodotDictionary();double at=Get(item,"time",0).AsDouble();if(time-h<at&&time>=at)impulse+=Get(item,"impulse",Vector3.Zero).AsVector3();if(time>=at&&time<at+Get(item,"duration",0).AsDouble())force+=Get(item,"force",Vector3.Zero).AsVector3();}return new Settings{["impulse"]=impulse,["force"]=force};}
    public void initialize(RefCounted owner,string id,Settings state,Settings config,double time)
    {
        var prototype=Map(owner,"prototypes")[id].AsGodotDictionary();var actor=prototype["actor"].As<Resource>();var pose=animated_world(owner,id,time,true,new Settings());state["pose"]=pose;state["initial_pose"]=pose;state["initial_time"]=time;state["initialized"]=true;int type=config["type"].AsInt32();state["type"]=type;state["sleep"]=0.0;var velocity=config["velocity"].AsVector3()+events(config,local(owner,actor,time),.0000001)["impulse"].AsVector3()/(float)Math.Max(.001,config["mass"].AsDouble());double rate=owner.Get("rate").AsDouble();if(config["inherit_velocity"].AsBool())velocity+=(animated_world(owner,id,time,false,new Settings()).Origin-animated_world(owner,id,time-1/rate,false,new Settings()).Origin)*(float)rate;state["v"]=velocity;state["w"]=config["angular_velocity"].AsVector3()*(Mathf.Pi/180);state["bones"]=new Settings();state["points"]=Array.Empty<Vector3>();state["velocities"]=Array.Empty<Vector3>();string attachmentId=config["attachment"].AsString();state["attachment_basis"]=attachmentId.Length>0?bone_world(owner,attachmentId,config["attachment_bone"].AsString(),time).Basis.Inverse()*pose.Basis:Basis.Identity;
        if(type is 1 or 4){ensure_graph(owner,id,state,config);var graph=prototype["graph"].AsGodotDictionary();string error=graph["error"].AsString();if(error.Length>0){warn(owner,actor.Get("display_name").AsString()+": "+error);return;}var points=graph["rest"].AsVector3Array();state["points"]=points;var velocities=new Vector3[points.Length];Array.Fill(velocities,velocity);state["velocities"]=velocities;}
        if(type==5){var start=pose.Origin;string endActor=config["end_actor"].AsString();var end=attachment(owner,endActor,config["end_bone"].AsString(),config["end_offset"].AsVector3(),time,pose*new Transform3D(Basis.Identity,new Vector3(0,-config["rope_length"].AsSingle(),0)));if(endActor.Length==0)end=pose*new Vector3(0,-config["rope_length"].AsSingle(),0);int count=Math.Clamp(config["rope_points"].AsInt32(),3,96);var points=new Vector3[count];for(int i=0;i<count;i++)points[i]=start.Lerp(end,(float)i/(count-1));state["points"]=points;var velocities=new Vector3[count];Array.Fill(velocities,velocity);state["velocities"]=velocities;var edges=new GArray();for(int i=0;i<count-1;i++)edges.Add(new GArray{i,i+1,config["rope_length"].AsDouble()/(count-1),false});prototype["graph"]=new Settings{["rest"]=(Vector3[])points.Clone(),["local"]=Array.Empty<Vector3>(),["edges"]=edges,["error"]="",["bindings"]=new GArray()};prototype["graph_key"]=state["initial_time"].ToString()+":5";}
        if(type==3){var bones=Get(Values(actor),"rig_bones",new GArray()).AsGodotArray();if(bones.Count==0)warn(owner,actor.Get("display_name").AsString()+": Skeleton physics needs a Skeleton Rig actor.");var names=config["bones"].AsGodotArray();foreach(var name in names)if(!bones.Any(value=>value.AsGodotDictionary()["name"].AsString()==name.AsString()))warn(owner,actor.Get("display_name").AsString()+": missing bone "+name.AsString());for(int i=0;i<bones.Count;i++){string name=bones[i].AsGodotDictionary()["name"].AsString();if(!names.Contains(name))continue;var bonePose=bone_world(owner,id,name,time);float length=.3f;var axis=Vector3.Up;foreach(var value in bones){var child=value.AsGodotDictionary();var rest=child["rest"].AsTransform3D().Origin;if(child["parent"].AsInt32()==i&&rest.Length()>.001){length=rest.Length();axis=rest.Normalized();break;}}state["bones"].AsGodotDictionary()[name]=new Settings{["pose"]=bonePose,["point"]=bonePose*(axis*length),["v"]=velocity,["axis"]=axis,["length"]=length,["index"]=i,["anchor"]=bonePose.Origin,["root_v"]=velocity};}}
        if(type==6)GD.Load<GDScript>("res://scripts/actors/physics/fluid/fluid_bridge.gd").Call("initialize",owner,id,state,config,time);if(type==7)Module(owner,"powder").Call("initialize",owner,id,state,config,time);if(type==8)_growth.initialize(owner,id,state,config,time);if(type==9)GD.Load<GDScript>("res://scripts/actors/fog/fog_motion_bridge.gd").Call("initialize",owner,id,state,config,time);
    }
    public void ensure_graph(RefCounted owner,string id,Settings state,Settings config){var prototype=Map(owner,"prototypes")[id].AsGodotDictionary();string key=state["initial_time"].ToString()+":"+state["type"].ToString();if(prototype["graph_key"].AsString()==key&&prototype["graph"].AsGodotDictionary().Count>0)return;prototype["graph"]=GD.Load<GDScript>("res://scripts/actors/physics/physics_geometry.gd").Call("particles",simulation_geometry(owner,id,state,new Settings()),config["particles"].AsInt32(),state["initial_pose"]);prototype["graph_key"]=key;}
}
